    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Join consecutive non-background cells in each row and column.
    for r in range(h):
        points = [c for c in range(w) if grid[r][c] != background]
        for a, b in zip(points, points[1:]):
            for c in range(a + 1, b):
                out[r][c] = 3

    for c in range(w):
        points = [r for r in range(h) if grid[r][c] != background]
        for a, b in zip(points, points[1:]):
            for r in range(a + 1, b):
                out[r][c] = 3

    return out
